# (feastDate, name, tradition, description, patronOf) - September to December
CA = "catholic,anglican"
C = "catholic"
CO = "catholic,orthodox"
COA = "catholic,orthodox,anglican"
CPA = "catholic,protestant,anglican"

DATA = [
    ("September 1", "Saint Giles", COA, "Hermit of the seventh or eighth century who lived in southern France and founded an abbey near Arles. Tradition holds he sheltered a wounded deer, and he is invoked as protector of the vulnerable.", "Hermits, the disabled, nursing mothers"),
    ("September 2", "The Martyrs of September", C, "More than a hundred priests and religious killed in Paris in September 1792 for refusing to swear loyalty to the revolutionary state's church. They died praying and forgiving.", "The persecuted, priests"),
    ("September 4", "Saint Rose of Viterbo", C, "Italian teenager (1233-1251) who preached in the streets of Viterbo, calling people to faith during a time of conflict. She was refused admission to a convent and lived in prayer at home.", "Young people, those rejected"),
    ("September 6", "Saint Bega", CA, "Seventh-century Irish princess who fled an arranged marriage and settled in Cumbria as a hermit. Tradition says she founded the nunnery at St Bees, which bears her name.", "Cumbria, women religious"),
    ("September 7", "Saints Stephen Pongracz, Melchior Grodziecki and Mark Krizin", C, "Three priests martyred in Kosice in 1619 for refusing to renounce their faith. They are remembered as witnesses to fidelity in the divided Europe of their day.", "Central Europe, those who stand firm in faith"),
    ("September 8", "The Nativity of the Blessed Virgin Mary", COA, "The Church celebrates the birthday of Mary, nine months after the feast of the Immaculate Conception. Her birth heralds the dawn of salvation, for Christ is born of her.", "Expectant mothers, Marian devotion"),
    ("September 9", "Saint Peter Claver", C, "Spanish Jesuit (1580-1654) who ministered to enslaved Africans arriving in Cartagena, Colombia. He baptised some 300,000 people and called himself 'the slave of the slaves forever'.", "Enslaved people, race relations, Colombia"),
    ("September 10", "Saint Nicholas of Tolentino", C, "Italian Augustinian friar (c. 1245-1305) who preached, heard confessions and visited the sick. He is remembered for devotion to the souls in purgatory and the 'bread of Saint Nicholas'.", "Souls in purgatory, sailors, the sick"),
    ("September 11", "Saints Protus and Hyacinth", C, "Two Roman brothers or servants martyred in the third century. Their tomb in the catacombs of Saint Hermes was found intact in the nineteenth century.", "Martyrs of Rome"),
    ("September 12", "The Holy Name of Mary", C, "A feast honouring the name of Mary, first celebrated in Spain and extended to the Church after the Christian victory at Vienna in 1683.", "Those who call on Mary's name"),
    ("September 14", "The Exaltation of the Holy Cross", "all", "The Church lifts up the cross as the sign of Christ's victory. The feast recalls the finding of the True Cross in Jerusalem and the triumph of love over death.", "Those who suffer, Christians everywhere"),
    ("September 15", "Our Lady of Sorrows", C, "A feast recalling the sorrows of Mary, from Simeon's prophecy to her standing beneath the cross. Mary shares in her Son's suffering and comforts those who grieve.", "Those in grief, mothers who have lost children"),
    ("September 18", "Saint Joseph of Cupertino", C, "Italian Franciscan (1603-1663) who struggled with learning but was marked by childlike faith and accounts of ecstasies. He is the patron of students and those who sit exams.", "Students, pilots, those in exams"),
    ("September 19", "Saint Januarius", C, "Bishop of Benevento martyred around 305 near Naples. A vial said to contain his blood is kept in Naples and, as tradition holds, liquefies on his feast.", "Naples, blood donors"),
    ("September 20", "Saints Andrew Kim Taegon, Paul Chong Hasang and Companions", CA, "103 Korean martyrs killed between 1839 and 1867, among them the first Korean priest, Andrew Kim, and many laypeople. Korea's church began largely through lay believers.", "Korea, lay Christians"),
    ("September 22", "Saint Maurice and Companions", COA, "Commander of the Theban Legion, said to have been martyred in Switzerland around 287 with his men for refusing to take part in pagan sacrifices.", "Soldiers, those who refuse unjust orders"),
    ("September 25", "Saint Sergius of Radonezh", "orthodox", "Russian monk (c. 1314-1392) who founded the Trinity Lavra and became spiritual father of the Russian people. He blessed Prince Dmitri before the battle that began Russian freedom.", "Russia, monks, those who seek peace"),
    ("September 26", "Saints Cosmas and Damian", COA, "Twin brothers, physicians in Syria, who treated the sick without payment and were martyred around 287. They are honoured among the 'holy unmercenaries'.", "Physicians, surgeons, pharmacists"),
    ("September 28", "Saint Wenceslaus of Bohemia", COA, "Duke of Bohemia (c. 907-935) who ruled with humility and generosity and was murdered by his brother. The Christmas carol 'Good King Wenceslas' honours his charity.", "Czech lands, rulers, those who give to the poor"),

    ("October 2", "The Holy Guardian Angels", CA, "A feast thanking God for the angels who watch over each person. Scripture and tradition teach that each of us is entrusted to the care of a guardian from birth until death.", "All people, children, travellers"),
    ("October 3", "Saint Dionysius the Areopagite", "orthodox", "Athenian convert of Saint Paul on the Areopagus, according to the Acts of the Apostles, who became the first bishop of Athens. Tradition honours him as a martyr.", "Athens, converts, theologians"),
    ("October 7", "Our Lady of the Rosary", C, "Pope Pius V established this feast in 1571 after the naval victory at Lepanto, attributed to the prayer of the Rosary. It invites the faithful to meditate on the life of Christ with Mary.", "Rosary devotion, families"),
    ("October 8", "Saint Pelagia of Antioch", CO, "A fifteen-year-old girl of Antioch who, rather than be taken by soldiers, threw herself from a rooftop and died, according to tradition, in 311 or 312. She is honoured as a martyr of purity.", "Young women, those under threat"),
    ("October 10", "Saint Francis Borgia", C, "Spanish duke (1510-1572) who became a Jesuit after the death of his wife. As third superior general, he strengthened the order's schools and missions.", "Those who change their lives, widowers"),
    ("October 11", "Saint John XXIII", C, "Pope from 1958 to 1963 known as 'Good Pope John' who called the Second Vatican Council. He was admired for his warmth, humour and humility.", "Christian unity, the Church's renewal"),
    ("October 13", "Saint Edward the Confessor", CA, "King of England (c. 1003-1066) known for piety and generosity. He rebuilt Westminster Abbey and was revered as the 'patron of kings' by English monarchs.", "Kings, difficult marriages, England"),
    ("October 14", "Pope Saint Callistus I", C, "Pope from about 217 to 222, a former slave who became bishop of Rome. He extended mercy to repentant sinners and gave his name to the catacombs of Saint Callistus.", "Cemetery workers, the repentant"),
    ("October 19", "Saints John de Brebeuf, Isaac Jogues and Companions", CA, "Eight Jesuit missionaries and lay helpers martyred in the 1640s in North America. They lived among the Huron and other peoples and are patrons of Canada.", "Canada, North American missionaries"),
    ("October 20", "Saint Paul of the Cross", C, "Italian mystic (1694-1775) who founded the Passionists to preach the love of Christ shown in his Passion. He directed souls in the deepest prayer and loved the poor.", "Those in suffering, retreat directors"),
    ("October 21", "Saint Hilarion", COA, "Palestinian hermit (c. 291-371) who lived in the desert near Gaza and brought monasticism to Palestine. Many came to him seeking guidance and healing.", "Hermits, spiritual seekers"),
    ("October 23", "Saint John of Capistrano", C, "Italian Franciscan (1386-1456) who preached across Europe, reformed the order and helped organise the defence of Belgrade in 1456 against the Ottoman advance.", "Jurists, military chaplains"),
    ("October 24", "Saint Anthony Mary Claret", C, "Spanish priest and missionary bishop (1807-1870) who founded the Claretians and served in Cuba. He preached in the open air and used the press to spread the Gospel.", "Missionaries, weavers, publishers"),
    ("October 25", "The Forty Martyrs of England and Wales", C, "Forty Catholics, priests and laypeople, executed between 1535 and 1679 for their faith. They died on the scaffold, often forgiving those who condemned them.", "England, Wales, those facing persecution"),
    ("October 26", "Alfred the Great", "anglican", "King of Wessex (849-899) who defended Christian England against Viking invaders, promoted learning and translated books into English. He was a wise and merciful ruler.", "England, rulers, scholars"),
    ("October 27", "Saint Frumentius", COA, "Syrian-born missionary (d. c. 380) captured as a boy and brought to Axum, who later became the first bishop of Ethiopia, ordained by Saint Athanasius.", "Ethiopia, missionaries"),
    ("October 29", "Saint Narcissus of Jerusalem", CO, "Bishop of Jerusalem (c. 99-215) who, tradition says, changed water to oil for the lamps on Easter vigil. After false accusations he retired as a hermit and later returned.", "Bishops, those who forgive slander"),
    ("October 30", "Saint Alphonsus Rodriguez", C, "Spanish Jesuit lay brother (1533-1617) who after the death of his wife and children became porter of a college in Majorca. He gave guidance to students, including Saint Peter Claver.", "Porters, the bereaved"),
    ("October 31", "Saint Wolfgang of Regensburg", C, "German bishop (c. 924-994) who reformed monasteries, cared for the poor and educated the future emperor Henry II. He later lived as a hermit in Austria.", "Bishops, carpenters, stroke patients"),

    ("November 1", "All Saints", "all", "The Church honours all those who have lived and died in Christ and now rejoice in heaven, known and unknown. It is a feast of hope for all who follow the way of holiness.", "All the saints, all of the faithful"),
    ("November 2", "The Commemoration of All the Faithful Departed", CA, "All Souls' Day is a day of prayer for those who have died. The Church remembers family, friends and strangers and entrusts them to the mercy of God.", "The faithful departed, the bereaved"),
    ("November 4", "Saint Charles Borromeo", C, "Archbishop of Milan (1538-1584) who implemented the reforms of the Council of Trent, founded seminaries and ministered to the plague-stricken of Milan.", "Bishops, seminarians, catechists"),
    ("November 5", "Saints Zechariah and Elizabeth", CO, "The parents of John the Baptist, described in Luke's Gospel as righteous before God. Elizabeth welcomed Mary at the Visitation, and Zechariah proclaimed the Benedictus.", "Parents, those who wait for answered prayer"),
    ("November 6", "Saint Leonard of Noblac", C, "Frankish hermit of the sixth century, said to have been freed from prison through the prayer of Saint Remigius. He is invoked by prisoners and captives.", "Prisoners, captives"),
    ("November 7", "Saint Willibrord", CA, "Northumbrian monk (658-739) who became the first bishop of Utrecht and apostle of the Frisians. He founded the abbey of Echternach in Luxembourg.", "The Netherlands, Luxembourg, missionaries"),
    ("November 8", "Blessed John Duns Scotus", C, "Scottish Franciscan philosopher and theologian (c. 1266-1308), the 'Subtle Doctor', who defended the Immaculate Conception and taught that Christ's incarnation springs from love.", "Philosophers, students of theology"),
    ("November 10", "Pope Saint Leo the Great", CA, "Pope from 440 to 461 whose letter to Flavian shaped the Council of Chalcedon's teaching on Christ. He met Attila and persuaded him to spare Rome.", "Popes, those who seek peace, theologians"),
    ("November 11", "Saint Martin of Tours", "all", "Roman soldier (c. 316-397) who cut his cloak in two to share with a beggar and later became bishop of Tours. His generosity made him one of the best-loved saints of Europe.", "Soldiers, the poor, those who give"),
    ("November 12", "Saint Josaphat", C, "Ukrainian Basilian monk and archbishop of Polotsk (c. 1580-1623) who worked for unity between Eastern and Western Christians. He was martyred and is honoured in the Eastern Catholic Churches.", "Church unity, Eastern Catholics"),
    ("November 16", "Saint Margaret of Scotland", CA, "Anglo-Saxon princess (c. 1045-1093) who became queen of Scotland. She cared for orphans and the poor, reformed church life and was a devoted mother of eight.", "Scotland, mothers, queens"),
    ("November 18", "Dedication of the Basilicas of Saints Peter and Paul", C, "The feast marks the dedication of the great basilicas in Rome built over the tombs of the two apostles. It reminds us of the Church's roots in apostolic witness.", "Rome, the apostolic Church"),
    ("November 19", "Saint Mechtilde of Helfta", C, "German Benedictine nun and mystic (1240-1298) at the monastery of Helfta. Her visions of the Sacred Heart and her prayers were widely read in the Middle Ages.", "Mystics, nuns"),
    ("November 20", "Saint Edmund the Martyr", CA, "King of East Anglia (c. 841-869) killed by Danish invaders after refusing to renounce Christ. He became one of England's most honoured martyr-kings.", "Kings, East Anglia, those facing persecution"),
    ("November 21", "The Presentation of the Blessed Virgin Mary", COA, "A feast marking the dedication of Mary to God in the Temple as a child. It recalls her complete offering of herself, long before the Annunciation.", "Children consecrated to God"),
    ("November 24", "Saint Andrew Dung-Lac and Companions", C, "117 Vietnamese martyrs killed between 1625 and 1886, including priests, catechists and laypeople. Their witness is the foundation of the Church in Vietnam.", "Vietnam, the persecuted"),
    ("November 26", "Saint Leonard of Port Maurice", C, "Italian Franciscan (1676-1751) who preached parish missions throughout Italy and promoted the Stations of the Cross. He is the patron of parish missions.", "Parish missionaries, the Stations of the Cross"),
    ("November 27", "Saint Virgil of Salzburg", C, "Irish monk (c. 700-784) who became bishop of Salzburg and encouraged scholarship. He championed a mission to the Slavs and completed the cathedral of Salzburg.", "Salzburg, scholars"),
    ("November 28", "Saint Catherine Laboure", C, "French Daughter of Charity (1806-1876) who in 1830 saw Mary and received the design of the Miraculous Medal. She served quietly for decades as a nurse of the elderly.", "The Miraculous Medal, the elderly, nurses"),
    ("November 29", "Saint Saturninus of Toulouse", C, "First bishop of Toulouse, martyred around 257 after refusing to sacrifice. According to tradition he was tied to a bull and dragged through the streets of the city.", "Toulouse, martyrs"),

    ("December 1", "Blessed Charles de Foucauld", CA, "French soldier turned hermit (1858-1916) who lived among the Tuareg in the Sahara, serving through quiet friendship and prayer. His spiritual vision inspired the Little Brothers of Jesus.", "Hermits, those who live among strangers"),
    ("December 2", "Saint Raphael Kalinowski", C, "Polish engineer and soldier (1835-1907) who endured exile in Siberia before becoming a Carmelite. He restored the Discalced Carmelites in Poland and promoted Christian unity.", "Exiles, Carmelites, Polish people"),
    ("December 5", "Saint Sabbas the Sanctified", CO, "Palestinian abbot (439-532) who founded the monastery of Mar Saba in the Judean desert, which has continued to this day. He guided thousands of monks and defended Chalcedon.", "Monks, those who live in the desert"),
    ("December 8", "The Immaculate Conception of the Blessed Virgin Mary", C, "The Church celebrates the belief that Mary was preserved from original sin from the first moment of her existence, in view of the merits of her Son.", "Mary, the Americas, Spain"),
    ("December 10", "Our Lady of Loreto", C, "A feast recalling the tradition of the Holy House of Nazareth, said to have been carried to Loreto, Italy. It honours the Holy Family's home and the mystery of the Incarnation.", "Pilots, those who travel by air"),
    ("December 11", "Pope Saint Damasus I", C, "Pope from 366 to 384 who commissioned Saint Jerome to prepare a Latin translation of the Bible. He restored the catacombs and honoured the martyrs with verses.", "Archaeologists, Bible translators"),
    ("December 15", "Saint Virginia Centurione Bracelli", C, "Genoese widow (1587-1651) who gave her life to the poor and abandoned, opening a hospice and organizing aid for those in need. She was canonized in 2003.", "The poor, widows"),
    ("December 16", "Saint Adelaide of Burgundy", C, "Empress (931-999) who endured imprisonment and exile and later reigned as co-regent. She used her power to found monasteries and care for the poor.", "Empresses, second marriages, the abused"),
    ("December 17", "Saint Olympias", CO, "Constantinopolitan widow and deaconess (c. 361-408) who gave away her wealth to the Church and the poor. She stood loyally with Saint John Chrysostom during his exile.", "Widows, deaconesses"),
    ("December 18", "Saint Gatian of Tours", C, "Traditional first bishop of Tours (third century) who evangelised Gaul and ministered in secret during persecution, celebrating Mass in caves.", "Tours, missionaries"),
    ("December 19", "Blessed Urban V", C, "Pope from 1362 to 1370 who tried to restore the papacy to Rome from Avignon. He supported education, founded colleges and lived a simple life.", "Students, reformers"),
    ("December 20", "Saint Dominic of Silos", C, "Spanish Benedictine abbot (c. 1000-1073) who renewed the monastery of Silos and ransomed captives from the Moors. He is invoked by expectant mothers.", "Prisoners, shepherds, expectant mothers"),
    ("December 22", "Saint Frances Xavier Cabrini", C, "Italian-born sister (1850-1917) who founded the Missionary Sisters of the Sacred Heart and served Italian immigrants in the United States, building hospitals, schools and orphanages.", "Immigrants, hospital administrators"),
    ("December 23", "Saint John of Kanty", C, "Polish priest and professor (1390-1473) at Krakow known for generosity to the poor and for his humility. He taught with gentleness and lived frugally.", "Teachers, students, Poland"),
    ("December 24", "Saints Adam and Eve", COA, "The Church remembers the first parents on the eve of Christmas, as Christ comes to restore what was lost. Their story is the beginning of the promise of salvation.", "Families, those who hope for redemption"),
    ("December 25", "The Nativity of the Lord", "all", "On Christmas the Church celebrates the birth of Jesus in Bethlehem. God becomes a child, laid in a manger, as the sign of his closeness to every person.", "All of humanity, children"),
    ("December 28", "The Holy Innocents", "all", "The children of Bethlehem killed by King Herod in his attempt to destroy the infant Jesus. The Church honours them as the first martyrs, who gave witness not by words but by their deaths.", "Children, those who suffer violence"),
    ("December 29", "Saint Thomas Becket", CA, "Archbishop of Canterbury (c. 1118-1170) who defended the freedom of the Church against King Henry II and was murdered in his cathedral. His shrine drew pilgrims for centuries.", "Secular clergy, those who stand for conscience"),
    ("December 30", "Saint Sabinus of Spoleto", C, "Bishop of Assisi martyred around 303 under Diocletian. He is honoured in central Italy for his steadfast faith and for the healing of a blind man.", "Italy, martyrs"),
    ("December 31", "Pope Saint Sylvester I", C, "Pope from 314 to 335 during the reign of Constantine. The Church grew in peace and the first Roman basilicas were built. The year ends on his feast day.", "The end of the year, thanksgiving"),
]
